});

// Security: Add input validation and pagination
app.get('/users', validate(userQuerySchema), (req, res) => {
  const { limit, offset } = req.query;

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Security: Apply pagination to prevent returning all data at once
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit,
      offset,
      total: users.length,
    },
  });
});

// Security: Global error handling middleware (MUST be last)
app.use((err, req, res, next) => {
  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  console.error('Error:', err); // Log for debugging

  res.status(err.status || 500).json({
    error: message,
  });
});

