const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { z } = require('zod'); // Input validation library

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security-related HTTP headers
app.use(helmet());

// Prevent DOS attacks by limiting repeated requests
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// Parse JSON with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));

// Prevent URL-encoded body parsing attacks
app.use(express.urlencoded({ extended: true, limit: '10kb', parameterLimit: 100 }));

// Disable server header to avoid information disclosure
app.disable('x-powered-by');

// ============================================
