      results.push({ service: 'DATABASE', status: 'canary', error: 'Contains CANARY' });
    } else {
      console.log('❌ Database connection failed:', err.message);
      results.push({ service: 'DATABASE', status: 'invalid', error: err.message });
    }
  }
}

