  return new Promise((resolve) => {
    console.log('\n🌐 Testing AWS_ACCESS_KEY_ID...');

    // AWS STS GetCallerIdentity - doesn't require specific permissions beyond being valid
    const params = {
      method: 'POST',
      host: 'sts.amazonaws.com',
