      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ AWS credentials are valid');
          results.push({ service: 'AWS', status: 'valid' });
        } else {
          console.log('❌ AWS credentials invalid:', res.statusCode);
          results.push({ service: 'AWS', status: 'invalid', code: res.statusCode });
        }
        resolve();
      });
    });

    req.on('error', (err) => {
      console.log('❌ AWS request failed:', err.message);
      results.push({ service: 'AWS', status: 'error', error: err.message });
      resolve();
    });

    // Create presigned URL for GetCallerIdentity
    const AWS = require('aws-sdk');
    const sts = new AWS.STS();
    sts.getCallerIdentity({}, (err, data) => {
      if (err) {
        if (err.message.includes('CANARY')) {
          console.log('⚠️  Canary value detected');
