// Tests connectivity and validity of environment variables from .env.test

const https = require('https');
const net = require('net');
const fs = require('fs');

// Parse .env.test manually
function loadEnvTest() {
  const content = fs.readFileSync('.env.test', 'utf8');
  const env = {};
  content.split('\n').forEach(line => {
    const match = line.match(/^([A-Z_]+)=(.*)$/);
    if (match) env[match[1]] = match[2];
  });
  return env;
}

const env = loadEnvTest();

// Helper to make HTTP requests
function httpsRequest(hostname, path, options = {}) {
  return new Promise((resolve, reject) => {
    const url = new URL(path, `https://${hostname}`);
    const req = https.request({
      hostname: url.hostname,
      port: 443,
      path: url.pathname + url.search,
      method: options.method || 'GET',
      headers: options.headers || {},
      timeout: 5000
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });
    if (options.body) req.write(options.body);
    req.end();
  });
}

// Test TCP connectivity (for database)
function testTcpConnection(host, port) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(3000);

    socket.on('connect', () => {
      socket.destroy();
      resolve({ reachable: true, error: null });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ reachable: false, error: 'Connection timeout' });
    });

    socket.on('error', (err) => {
      resolve({ reachable: false, error: err.message });
    });

    socket.connect(port, host);
  });
}

