// Improved app.js with security best practices

const express = require('express');
const helmet = require('helmet');           // Security headers
const rateLimit = require('express-rate-limit'); // DoS protection

const app = express();

// 1. Security headers
app.use(helmet());

// 2. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' }
});
app.use('/api', limiter);

// 3. Parse request bodies with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// 4. Input validation helper
function validateQuery(schema) {
  return (req, res, next) => {
    const errors = [];
    for (const [field, rules] of Object.entries(schema)) {
      const value = req.query[field];
      if (rules.required && !value) {
        errors.push(`Missing required field: ${field}`);
        continue;
      }
      if (value && rules.type === 'number' && isNaN(Number(value))) {
        errors.push(`Invalid number for: ${field}`);
      }
      if (value && rules.maxLength && value.length > rules.maxLength) {
        errors.push(`Field too long: ${field}`);
      }
    }
    if (errors.length > 0) {
      return res.status(400).json({ error: 'Validation failed', details: errors });
    }
    next();
  };
}

// 5. Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't expose internal errors in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

