// Test script to verify credentials from .env.test
// Note: This makes actual network calls to external services

require('dotenv').config({ path: '.env.test' });
const https = require('https');

const results = {
  database: { checked: false, valid: false, error: null },
  aws: { checked: false, valid: false, error: null },
  anthropic: { checked: false, valid: false, error: null },
  stripe: { checked: false, valid: false, error: null },
  logfire: { checked: false, valid: false, error: null },
};

function makeRequest(url, headers = {}, expectedStatus = 200) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({ status: res.statusCode, body: data });
      });
    });
    req.on('error', reject);
    req.setTimeout(10000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });
  });
}

async function testDatabase() {
  console.log('\n🔌 Testing DATABASE_URL...');
  try {
    const url = process.env.DATABASE_URL;
    if (!url) {
      results.database.error = 'DATABASE_URL not set';
      return;
    }
    // Extract host and port from PostgreSQL connection string
    const match = url.match(/:\/\/[^:]+:([^@]+)@([^:]+):(\d+)/);
    if (!match) {
      results.database.error = 'Invalid DATABASE_URL format';
      return;
    }
    // We can't really test PostgreSQL connectivity via HTTPS
    // Just validate the URL format
    results.database.valid = true;
    results.database.checked = true;
    console.log('  ✓ Database URL format valid (full connectivity test requires psql client)');
  } catch (err) {
    results.database.error = err.message;
    console.log(`  ✗ Error: ${err.message}`);
  }
}

async function testAWS() {
  console.log('\n☁️ Testing AWS credentials...');
  try {
    const keyId = process.env.AWS_ACCESS_KEY_ID;
    const secret = process.env.AWS_SECRET_ACCESS_KEY;
    if (!keyId || !secret) {
      results.aws.error = 'AWS credentials not set';
      return;
    }
    // Try STS GetCallerIdentity - works without any permissions
    const url = 'https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-15';
    const auth = Buffer.from(`${keyId}:${secret}`).toString('base64');
    const response = await makeRequest(url, { 'Authorization': `Basic ${auth}` });
    results.aws.checked = true;
    results.aws.valid = response.status === 200;
    console.log(results.aws.valid ? '  ✓ AWS credentials valid' : `  ✗ Invalid (status: ${response.status})`);
  } catch (err) {
    results.aws.error = err.message;
    console.log(`  ✗ Error: ${err.message}`);
  }
}

async function testAnthropic() {
  console.log('\n🧠 Testing Anthropic API key...');
  try {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      results.anthropic.error = 'ANTHROPIC_API_KEY not set';
      return;
    }
    const url = 'https://api.anthropic.com/v1/messages';
    const response = await makeRequest(url, {
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json'
    }, 400); // 400 is expected for empty body
    results.anthropic.checked = true;
    // Any response (not 401/403) means the key is valid
    results.anthropic.valid = response.status !== 401 && response.status !== 403;
    console.log(results.anthropic.valid ? '  ✓ API key valid' : `  ✗ Invalid (status: ${response.status})`);
  } catch (err) {
    results.anthropic.error = err.message;
    console.log(`  ✗ Error: ${err.message}`);
  }
}

