async function main() {
  console.log('========================================');
  console.log('Credential Validation Test');
  console.log('========================================');

  if (!process.env.DATABASE_URL) {
    console.log('\n⚠️ No .env.test file found or DATABASE_URL not set');
    console.log('Run: source .env.test && node test-credentials.js');
