  const totalChecked = Object.values(results).filter(r => r.checked).length;

  console.log(`Valid: ${validCount}/${totalChecked}`);

  const invalid = Object.entries(results)
    .filter(([k, v]) => v.checked && !v.valid)
    .map(([k]) => k);

  if (invalid.length > 0) {
